class _SyncReviews:
    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def create(
        self,
        owner: str,
        pull_request_number: int,
        repo: str,
        *,
        post: Union[bool, None] = None,
        scope: Union[models.ReviewScope, None] = None,
    ) -> models.Review:
        """Create Review

        Run a code review on demand.

        Reviews an open pull request. Which pipeline runs is not a
        parameter: it resolves from the repository's files exactly as
        it does for a push, so an on-demand review never disagrees with
        the automatic one.

        A review is one pipeline run over one commit range, with one
        agent session per stage: `review.id` is the run id, and
        `stages[].session_id` is where a client streams
        (/sessions/{id}/stream on a stage session), since the review
        itself is a pipeline rather than one process.
        """
        path = "/v1/reviews"
        body_fields: dict[str, Any] = {
            "owner": owner,
            "post": post,
            "pull_request_number": pull_request_number,
            "repo": repo,
            "scope": scope,
        }
        body = build_body(
            models.CreateReviewRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = self._transport.request(
            "POST", path, response_model=models.Review, json_body=body
        )
        assert response is not None
        return response

    def get(
        self,
        review_id: str,
    ) -> models.Review:
        """Get Review

        Return one review with findings and outcome.

        Includes its scope, the per-stage sessions, the parsed findings,
        the finding counters, and the posting outcome.

        Findings only exist after a stage session finalizes — a running
        review honestly reports [] / null, which is why a client
        streams a stage session and then re-fetches the review.
        """
        path = f"/v1/reviews/{_quote(review_id)}"
        response = self._transport.request("GET", path, response_model=models.Review)
        assert response is not None
        return response

    def list(
        self,
        *,
        repository: Union[List[str], None] = None,
        pull_request_number: Union[List[int], None] = None,
        status: Union[List[models.CodeReviewRunStatus], None] = None,
        start: Union[datetime, None] = None,
        end: Union[datetime, None] = None,
        limit: Union[int, None] = None,
        cursor: Union[str, None] = None,
    ) -> SyncPage[models.Review, models.ReviewsListResponse]:
        """List Reviews

        List code reviews, newest first.

        `findings` and `configuration` are omitted (counters only). Each
        filter is a set: repeat `repository`, `pull_request_number`, or
        `status` to match any of several values. `start` and `end` bound
        the review's creation time.

        Webhook-created reviews appear here too, so this answers "show
        me every review on this PR".
        """
        path = "/v1/reviews"
        query = build_query(
            {
                "repository": repository,
                "pull_request_number": pull_request_number,
                "status": status,
                "start": start,
                "end": end,
                "limit": limit,
                "cursor": cursor,
            }
        )
        response = self._transport.request(
            "GET", path, response_model=models.ReviewsListResponse, query=query
        )
        assert response is not None
        return SyncPage(
            response,
            "reviews",
            lambda _cursor: self.list(
                repository=repository,
                pull_request_number=pull_request_number,
                status=status,
                start=start,
                end=end,
                limit=limit,
                cursor=_cursor,
            ),
        )


