class _SyncSessions(SyncSessionsSugar):
    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def diff(
        self,
        session_id: str,
    ) -> models.SessionDiffResponse:
        """Get Agent Session Diff

        Return the session's uncommitted changes as a patch.

        One unified-diff section per changed file, captured from the
        sandbox's working tree when the session ended. The per-file
        counts ride on the session itself (`git.repos[].files`); this
        is the text behind them. Empty when the tree was clean. A
        sandbox token may read only its own session's diff.
        """
        path = f"/v1/sessions/{_quote(session_id)}/diff"
        response = self._transport.request(
            "GET", path, response_model=models.SessionDiffResponse
        )
        assert response is not None
        return response

    def export(
        self,
        session_id: str,
    ) -> models.GetSessionLogResponse:
        """Export Agent Session

        Export the complete session history.

        The complete, ordered history of the session (agent output, tool calls, thinking,
        lifecycle events, sandbox output, message events) as an ordered
        manifest of presigned segment URLs.

        Segments are gzip members: download in order and concatenate
        for one file. The JSON API never carries the bytes (same
        two-step as files). /records is the paged live view of the
        same data.
        """
        path = f"/v1/sessions/{_quote(session_id)}/export"
        response = self._transport.request(
            "GET", path, response_model=models.GetSessionLogResponse
        )
        assert response is not None
        return response

    def get(
        self,
        session_id: str,
    ) -> models.SessionResponse:
        """Get Agent Session

        Return one session.

        The public wire shape — the same shape the stream's session
        frames carry, with attributed_user and stopped_by_user resolved
        at read time.

        The heavy near-static blobs (config snapshot, input/output)
        live on the detail endpoints, not here.
        """
        path = f"/v1/sessions/{_quote(session_id)}"
        response = self._transport.request(
            "GET", path, response_model=models.SessionResponse
        )
        assert response is not None
        return response

    def ingest_transcript(
        self,
        session_id: str,
        lines: List[str],
        *,
        offset: Union[int, None] = None,
    ) -> models.TranscriptIngestResult:
        """Ingest Agent Session Transcript

        Append transcript lines to a session's record.

        The in-sandbox tailer for interactive sessions.

        A sandbox token may only push its own session's transcript.
        Idempotent by transcript line uuid; tolerant of malformed lines.
        """
        path = f"/v1/sessions/{_quote(session_id)}/transcript"
        body_fields: dict[str, Any] = {
            "lines": lines,
            "offset": offset,
        }
        body = build_body(
            models.IngestTranscriptRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = self._transport.request(
            "POST", path, response_model=models.TranscriptIngestResult, json_body=body
        )
        assert response is not None
        return response

    def list(
        self,
        *,
        automation: Union[str, None] = None,
        source: Union[List[models.SessionSource], None] = None,
        days: Union[int, None] = None,
        start: Union[datetime, None] = None,
        end: Union[datetime, None] = None,
        limit: Union[int, None] = None,
        cursor: Union[str, None] = None,
        author_id: Union[int, None] = None,
        repo: Union[str, None] = None,
        unfinished: Union[bool, None] = None,
    ) -> SyncPage[models.Session, models.SessionsListResponse]:
        """List Agent Sessions

        List cloud agent sessions, newest first.

        Optionally filtered by automation (id or name), source, time
        window, attributed author, repository, and whether the session is
        still going.
        """
        path = "/v1/sessions"
        query = build_query(
            {
                "automation": automation,
                "source": source,
                "days": days,
                "start": start,
                "end": end,
                "limit": limit,
                "cursor": cursor,
                "author_id": author_id,
                "repo": repo,
                "unfinished": unfinished,
            }
        )
        response = self._transport.request(
            "GET", path, response_model=models.SessionsListResponse, query=query
        )
        assert response is not None
        return SyncPage(
            response,
            "sessions",
            lambda _cursor: self.list(
                automation=automation,
                source=source,
                days=days,
                start=start,
                end=end,
                limit=limit,
                cursor=_cursor,
                author_id=author_id,
                repo=repo,
                unfinished=unfinished,
            ),
        )

    def output(
        self,
        session_id: str,
    ) -> None:
        """Get Agent Session Output

        Return the session's typed output.

        The payload the agent submitted through its config-declared
        output.json_schema, as the raw JSON body with no envelope. 404
        while the session is still running (poll GET /v1/sessions/{id}),
        when the agent declares no output block, or when no execution
        produced output.
        """
        path = f"/v1/sessions/{_quote(session_id)}/output"
        self._transport.request("GET", path, response_model=None)
        return None

    def records(
        self,
        session_id: str,
        *,
        cursor: Union[str, None] = None,
        limit: Union[int, None] = None,
    ) -> SyncPage[
        Union[
            models.ClaudeSessionRecord,
            models.CodexSessionRecord,
            models.LifecycleSessionRecord,
        ],
        models.SessionRecordsListResponse,
    ]:
        """Get Agent Session Records

        Return the session's stored transcript records, oldest first.

        Pagination is opt-in (cursor/limit); a bare call returns the
        full retained transcript. Available to sandbox tokens too: an
        agent answering "did X look into Y?" needs to read the sessions
        it finds, and any org member sees the same transcript in the
        dashboard.
        """
        path = f"/v1/sessions/{_quote(session_id)}/records"
        query = build_query(
            {
                "cursor": cursor,
                "limit": limit,
            }
        )
        response = self._transport.request(
            "GET", path, response_model=models.SessionRecordsListResponse, query=query
        )
        assert response is not None
        return SyncPage(
            response,
            "records",
            lambda _cursor: self.records(
                session_id=session_id, cursor=_cursor, limit=limit
            ),
        )

    def send_message(
        self,
        session_id: str,
        message: str,
        *,
        idempotency_key: Union[str, None] = None,
        images: Union[List[models.ImageAttachment], None] = None,
    ) -> models.SessionMessageResponse:
        """Send Agent Session Message

        Send a message to a session.

        409 for react/cron, non-interactive, and closed sessions.
        Returns the created message so the caller can track it by id; a
        retried send with the same idempotency_key returns the original
        message.
        """
        path = f"/v1/sessions/{_quote(session_id)}/messages"
        body_fields: dict[str, Any] = {
            "idempotency_key": idempotency_key,
            "images": images,
            "message": message,
        }
        body = build_body(
            models.SendSessionMessageRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = self._transport.request(
            "POST", path, response_model=models.SessionMessageResponse, json_body=body
        )
        assert response is not None
        return response

    def start(
        self,
        *,
        budget: Union[float, None] = None,
        claude: Union[models.ClaudeConfig, None] = None,
        codex: Union[models.CodexConfig, None] = None,
        environment: Union[str, models.EnvironmentConfig, None] = None,
        force_rebuild: Union[bool, None] = None,
        images: Union[List[models.ImageAttachment], None] = None,
        interactive: Union[bool, None] = None,
        metadata: Union[dict[str, str], None] = None,
        output: Union[models.OutputConfig, None] = None,
        permissions: Union[models.PermissionsConfig, None] = None,
        prompt: Union[str, None] = None,
        repositories: Union[List[str], None] = None,
        skills: Union[List[models.SkillRef], None] = None,
    ) -> models.SessionResponse:
        """Start Agent Session

        Start a cloud agent session.

        The daily driver: a prompt, optionally where to run it
        (`environment`) and the run's own settings, in the AutomationConfig
        vocabulary. What you send is what runs: omit `environment` and the
        session runs in the built-in basic sandbox. A missing model or
        budget comes from the organization's settings, so
        `{"prompt": "..."}` alone is a complete request. `prompt` is the
        first message; omit it and the session starts idle, waiting for
        one. 400 when `interactive` is false and there is no prompt, or
        when `budget` exceeds the organization's per-session ceiling. To
        run a saved automation, use POST /v1/automations/{automation_id}/sessions.
        """
        path = "/v1/sessions"
        body_fields: dict[str, Any] = {
            "budget": budget,
            "claude": claude,
            "codex": codex,
            "environment": environment,
            "force_rebuild": force_rebuild,
            "images": images,
            "interactive": interactive,
            "metadata": metadata,
            "output": output,
            "permissions": permissions,
            "prompt": prompt,
            "repositories": repositories,
            "skills": skills,
        }
        body = build_body(
            models.StartAgentSessionRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = self._transport.request(
            "POST", path, response_model=models.SessionResponse, json_body=body
        )
        assert response is not None
        return response

    def stop(
        self,
        session_id: str,
    ) -> models.SessionResponse:
        """Stop Agent Session

        Stop an in-flight session and return it.

        stopped_by is recorded only when the caller's credential maps
        to a GitHub account.
        """
        path = f"/v1/sessions/{_quote(session_id)}/stop"
        response = self._transport.request(
            "POST", path, response_model=models.SessionResponse
        )
        assert response is not None
        return response


