class Ellipsis:
    """The Ellipsis API client. `api_key` is a bearer credential from
    app.ellipsis.dev (an API key or a CLI login token)."""

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
        max_retries: int = MAX_RETRIES,
    ) -> None:
        self._transport = Transport(
            api_key=api_key,
            base_url=base_url,
            timeout=timeout,
            max_retries=max_retries,
        )
        self.alerts = _SyncAlerts(self._transport)
        self.analytics = _SyncAnalytics(self._transport)
        self.auth = _SyncAuth(self._transport)
        self.automations = _SyncAutomations(self._transport)
        self.environments = _SyncEnvironments(self._transport)
        self.files = _SyncFiles(self._transport)
        self.integrations = _SyncIntegrations(self._transport)
        self.memories = _SyncMemories(self._transport)
        self.models = _SyncModels(self._transport)
        self.reviews = _SyncReviews(self._transport)
        self.secrets = _SyncSecrets(self._transport)
        self.sessions = _SyncSessions(self._transport)
        self.settings = _SyncSettings(self._transport)
        self.templates = _SyncTemplates(self._transport)

    def close(self) -> None:
        self._transport.close()

    def __enter__(self) -> "Ellipsis":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def budget(
        self,
    ) -> models.BudgetSummary:
        """Get Budget

        Return the caller's current budget summary.
        """
        path = "/v1/budget"
        response = self._transport.request(
            "GET", path, response_model=models.BudgetSummary
        )
        assert response is not None
        return response

    def me(
        self,
    ) -> models.WhoAmIResponse:
        """Current Identity

        Return the identity behind the caller's credential.
        """
        path = "/v1/me"
        response = self._transport.request(
            "GET", path, response_model=models.WhoAmIResponse
        )
        assert response is not None
        return response

    def usage(
        self,
    ) -> models.GetUsageDashboardResponse:
        """Get Usage

        Return the caller's usage dashboard data.
        """
        path = "/v1/usage"
        response = self._transport.request(
            "GET", path, response_model=models.GetUsageDashboardResponse
        )
        assert response is not None
        return response


