class _AsyncMemories:
    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport

    async def create(
        self,
        content: str,
        description: str,
        path: str,
    ) -> models.MemoryResponse:
        """Create Memory

        Save a memory for future agent sessions.

        Memories are durable lessons shared across the whole
        organization — conventions, past decisions, known gotchas that an
        agent cannot derive from the repository itself. One concise fact
        per memory; the description is what a reader sees in the index.

        Creating never overwrites: a path that already exists is a 409, so
        correcting an existing memory is an explicit edit.
        """
        path = "/v1/memories"
        body_fields: dict[str, Any] = {
            "content": content,
            "description": description,
            "path": path,
        }
        body = build_body(
            models.CreateMemoryRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = await self._transport.request(
            "POST", path, response_model=models.MemoryResponse, json_body=body
        )
        assert response is not None
        return response

    async def delete(
        self,
        memory_id: str,
        *,
        if_sha256: Union[str, None] = None,
    ) -> None:
        """Delete Memory

        Delete a memory that is no longer true.

        Available to every credential type, agents included — a wrong
        memory is worse than a missing one. The deleted content is kept in
        the memory's history for forensics, not for an undo API.
        """
        path = f"/v1/memories/{_quote(memory_id)}"
        query = build_query(
            {
                "if_sha256": if_sha256,
            }
        )
        await self._transport.request("DELETE", path, response_model=None, query=query)
        return None

    async def edit(
        self,
        memory_id: str,
        *,
        content: Union[str, None] = None,
        description: Union[str, None] = None,
        if_sha256: Union[str, None] = None,
    ) -> models.MemoryResponse:
        """Edit Memory

        Correct an existing memory in place.

        Pass description, content, or both. This never creates a memory (an
        unknown id is a 404) and never moves one — the path is immutable, so
        relocating a memory is a delete plus a create.

        Pass `if_sha256` (from a previous read) to make a concurrent write
        a 409 instead of silently overwriting it.
        """
        path = f"/v1/memories/{_quote(memory_id)}"
        body_fields: dict[str, Any] = {
            "content": content,
            "description": description,
            "if_sha256": if_sha256,
        }
        body = build_body(
            models.EditMemoryRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = await self._transport.request(
            "PUT", path, response_model=models.MemoryResponse, json_body=body
        )
        assert response is not None
        return response

    async def get(
        self,
        memory_id: str,
    ) -> models.MemoryResponse:
        """Get Memory

        Read one memory's full content.

        The id comes from the index returned by listing memories.
        """
        path = f"/v1/memories/{_quote(memory_id)}"
        response = await self._transport.request(
            "GET", path, response_model=models.MemoryResponse
        )
        assert response is not None
        return response

    async def list(
        self,
        *,
        prefix: Union[str, None] = None,
    ) -> models.MemoriesListResponse:
        """List Memories

        List the organization's memories as a readable index.

        Returns the memories rendered as a markdown index (one line per
        memory, carrying its id, path, and description) plus the same
        entries structured, each with every field except `content`. Read
        the index, then fetch the ids whose content you want.
        """
        path = "/v1/memories"
        query = build_query(
            {
                "prefix": prefix,
            }
        )
        response = await self._transport.request(
            "GET", path, response_model=models.MemoriesListResponse, query=query
        )
        assert response is not None
        return response


class _AsyncModels:
    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport

    async def list(
        self,
    ) -> models.ModelsListResponse:
        """List Supported Models

        List selectable agent models.

        Most expensive first, with the platform default flagged.

        Reads the same registry as the dashboard's rate table, so a
        client's model picker can never drift from what's offered.
        Behind auth but not account-scoped — the selectable set is
        global.
        """
        path = "/v1/models"
        response = await self._transport.request(
            "GET", path, response_model=models.ModelsListResponse
        )
        assert response is not None
        return response


class _AsyncReviews:
    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport

    async def create(
        self,
        owner: str,
        pull_request_number: int,
        repo: str,
        *,
        post: Union[bool, None] = None,
        scope: Union[models.ReviewScope, None] = None,
    ) -> models.Review:
        """Create Review

        Run a code review on demand.

        Reviews an open pull request. Which pipeline runs is not a
        parameter: it resolves from the repository's files exactly as
        it does for a push, so an on-demand review never disagrees with
        the automatic one.

        A review is one pipeline run over one commit range, with one
        agent session per stage: `review.id` is the run id, and
        `stages[].session_id` is where a client streams
        (/sessions/{id}/stream on a stage session), since the review
        itself is a pipeline rather than one process.
        """
        path = "/v1/reviews"
        body_fields: dict[str, Any] = {
            "owner": owner,
            "post": post,
            "pull_request_number": pull_request_number,
            "repo": repo,
            "scope": scope,
        }
        body = build_body(
            models.CreateReviewRequest.model_validate(
                {k: v for k, v in body_fields.items() if v is not None}
            )
        )
        response = await self._transport.request(
            "POST", path, response_model=models.Review, json_body=body
        )
        assert response is not None
        return response

    async def get(
        self,
        review_id: str,
    ) -> models.Review:
        """Get Review

        Return one review with findings and outcome.

        Includes its scope, the per-stage sessions, the parsed findings,
        the finding counters, and the posting outcome.

        Findings only exist after a stage session finalizes — a running
        review honestly reports [] / null, which is why a client
        streams a stage session and then re-fetches the review.
        """
        path = f"/v1/reviews/{_quote(review_id)}"
        response = await self._transport.request(
            "GET", path, response_model=models.Review
        )
        assert response is not None
        return response

    async def list(
        self,
        *,
        repository: Union[List[str], None] = None,
        pull_request_number: Union[List[int], None] = None,
        status: Union[List[models.CodeReviewRunStatus], None] = None,
        start: Union[datetime, None] = None,
        end: Union[datetime, None] = None,
        limit: Union[int, None] = None,
        cursor: Union[str, None] = None,
    ) -> AsyncPage[models.Review, models.ReviewsListResponse]:
        """List Reviews

        List code reviews, newest first.

        `findings` and `configuration` are omitted (counters only). Each
        filter is a set: repeat `repository`, `pull_request_number`, or
        `status` to match any of several values. `start` and `end` bound
        the review's creation time.

        Webhook-created reviews appear here too, so this answers "show
        me every review on this PR".
        """
        path = "/v1/reviews"
        query = build_query(
            {
                "repository": repository,
                "pull_request_number": pull_request_number,
                "status": status,
                "start": start,
                "end": end,
                "limit": limit,
                "cursor": cursor,
            }
        )
        response = await self._transport.request(
            "GET", path, response_model=models.ReviewsListResponse, query=query
        )
        assert response is not None
        return AsyncPage(
            response,
            "reviews",
            lambda _cursor: self.list(
                repository=repository,
                pull_request_number=pull_request_number,
                status=status,
                start=start,
                end=end,
                limit=limit,
                cursor=_cursor,
            ),
        )


