class AsyncEllipsis:
    """The Ellipsis API client. `api_key` is a bearer credential from
    app.ellipsis.dev (an API key or a CLI login token)."""

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
        max_retries: int = MAX_RETRIES,
    ) -> None:
        self._transport = AsyncTransport(
            api_key=api_key,
            base_url=base_url,
            timeout=timeout,
            max_retries=max_retries,
        )
        self.alerts = _AsyncAlerts(self._transport)
        self.analytics = _AsyncAnalytics(self._transport)
        self.auth = _AsyncAuth(self._transport)
        self.automations = _AsyncAutomations(self._transport)
        self.environments = _AsyncEnvironments(self._transport)
        self.files = _AsyncFiles(self._transport)
        self.integrations = _AsyncIntegrations(self._transport)
        self.memories = _AsyncMemories(self._transport)
        self.models = _AsyncModels(self._transport)
        self.reviews = _AsyncReviews(self._transport)
        self.secrets = _AsyncSecrets(self._transport)
        self.sessions = _AsyncSessions(self._transport)
        self.settings = _AsyncSettings(self._transport)
        self.templates = _AsyncTemplates(self._transport)

    async def close(self) -> None:
        await self._transport.close()

    async def __aenter__(self) -> "AsyncEllipsis":
        return self

    async def __aexit__(self, *exc: object) -> None:
        await self.close()

    async def budget(
        self,
    ) -> models.BudgetSummary:
        """Get Budget

        Return the caller's current budget summary.
        """
        path = "/v1/budget"
        response = await self._transport.request(
            "GET", path, response_model=models.BudgetSummary
        )
        assert response is not None
        return response

    async def me(
        self,
    ) -> models.WhoAmIResponse:
        """Current Identity

        Return the identity behind the caller's credential.
        """
        path = "/v1/me"
        response = await self._transport.request(
            "GET", path, response_model=models.WhoAmIResponse
        )
        assert response is not None
        return response

    async def usage(
        self,
    ) -> models.GetUsageDashboardResponse:
        """Get Usage

        Return the caller's usage dashboard data.
        """
        path = "/v1/usage"
        response = await self._transport.request(
            "GET", path, response_model=models.GetUsageDashboardResponse
        )
        assert response is not None
        return response
